# First, let's check if there's a relay API we can call for MCP world tools
# The mcp.json shows it's at http://127.0.0.1:40573/mcp/bf02d917a8e3cd7ed9f25d5286efddf1
import json, urllib.request

def mcp_call(method, params=None):
    """Call MCP world API via HTTP relay."""
    url = "http://127.0.0.1:40573/mcp/bf02d917a8e3cd7ed9f25d5286efddf1"
    data = json.dumps({
        "jsonrpc": "2.0",
        "id": 1,
        "method": method,
        "params": params or {}
    }).encode()
    req = urllib.request.Request(
        url,
        data=data,
        headers={"Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            return json.loads(resp.read())
    except Exception as e:
        return f"ERR {e}"

# Test the relay
r = mcp_call("tools/list")
print("== tools/list ==")
print(r)

# Also try to search for routing policy emails
r2 = mcp_call("tools/call", {"name": "api_search", "arguments": {"query": "routing policy email"}})
